Definition chunk_redesc (off : Z) (e : sv) (c : YQ0b.chunk) : YQ0b.chunk :=
if Z.eqb (YQ0b.c_off c) off then match YQ0b.c_val c with CVal w _ => YQ0b.mkChunk off (CVal w e) | _ => c end else c.
Definition ss_rechunk_off (s : sstate) (base : nat) (off : Z) (e : sv) : sstate :=
ss_set_mem s (map (fun r => match YQ0b.r_base r with
| Some b => if Nat.eqb b base then YQ0b.mkRegion (YQ0b.r_base r) (YQ0b.r_lo r) (YQ0b.r_hi r) (YQ0b.r_wlo r) (YQ0b.r_whi r)
(map (chunk_redesc off e) (YQ0b.r_chunks r)) else r
| None => r end) (ss_mem s)).
