(forall blc lyq ownq i, In (pt, n) blc -> 0 <= i < n ->
awr_byte TFLUSH_STK (spZ (c_regs cx)) (fl_FP cx) (ablocks B (c_ly cx) (c_S cx)) blc lyq ownq (pt + i)) /\
aftok (fl_FP cx) (ablocks B (c_ly cx) (c_S cx)) (pt, n).
